#include "ENGINE/Source/Services/particlesystem.h"
#include "ENGINE/Source/Model/modelrender.h"
#include <cmath>
#include <stdexcept>
void CParticle::Copy(const CParticle&o){*this=o;}void CParticle::Destroy(){m_hmodel=nullptr;}
CParticleEmitter::CParticleEmitter(){Init();}CParticleEmitter::CParticleEmitter(const CParticleEmitter&o){Copy(o);}CParticleEmitter&CParticleEmitter::operator=(const CParticleEmitter&o){if(this!=&o)Copy(o);return*this;}CParticleEmitter::~CParticleEmitter(){Destroy();}void CParticleEmitter::Init(){m_refCount=1;m_numNew=0;m_enabled=m_enabled2=1;m_particleEmissionRate=0;m_particleLifeSpan=0;m_velocity=0;m_acceleration=0;m_scale=1;m_latitude=3.1415927F*.25F;m_longitude=3.1415927F*.25F;m_hmodel=nullptr;}void CParticleEmitter::Copy(const CParticleEmitter&o){Flush();m_numNew=o.m_numNew;m_enabled=o.m_enabled;m_enabled2=o.m_enabled2;m_particleEmissionRate=o.m_particleEmissionRate;m_particleLifeSpan=o.m_particleLifeSpan;m_velocity=o.m_velocity;m_acceleration=o.m_acceleration;m_scale=o.m_scale;m_latitude=o.m_latitude;m_longitude=o.m_longitude;m_hmodel=o.m_hmodel;}void CParticleEmitter::Destroy(){Flush();m_hmodel=nullptr;}void CParticleEmitter::SyncAllocation(){m_dead={};for(unsigned i=0;i<m_particles.size();++i)m_dead.Push(i);}unsigned CParticleEmitter::CreateParticle(){unsigned i;if(m_dead.Empty()){i=static_cast<unsigned>(m_particles.size());m_particles.emplace_back();}else i=m_dead.Pop();auto&p=m_particles[i];p.m_timeToLive=m_particleLifeSpan;p.m_elapsed=0;p.m_scale=m_scale;p.m_hmodel=m_hmodel;p.m_position={};float cp=std::cos(m_latitude);p.m_velocity={cp*std::cos(m_longitude)*m_velocity,cp*std::sin(m_longitude)*m_velocity,std::sin(m_latitude)*m_velocity};m_alive.Push(i);return i;}void CParticleEmitter::DestroyParticle(unsigned i){if(i<m_particles.size()){m_particles[i].m_timeToLive=0;m_dead.Push(i);}}void CParticleEmitter::MoveParticle(CParticle&p,float d){p.m_position+=p.m_velocity*d+NTempest::C3Vector{0,0,-m_acceleration}*(.5F*d*d);p.m_velocity.z-=m_acceleration*d;p.m_elapsed+=d;p.m_timeToLive=(std::max)(0.0F,p.m_timeToLive-d);}
double CParticleEmitter::Velocity()const{return m_velocity;}double CParticleEmitter::Acceleration()const{return m_acceleration;}double CParticleEmitter::Scale()const{return m_scale;}double CParticleEmitter::Latitude()const{return m_latitude;}double CParticleEmitter::Longitude()const{return m_longitude;}double CParticleEmitter::ParticleEmissionRate()const{return m_particleEmissionRate;}double CParticleEmitter::ParticleLifeSpan()const{return m_particleLifeSpan;}int CParticleEmitter::Enabled()const{return m_enabled;}int CParticleEmitter::Enabled2()const{return m_enabled2;}void CParticleEmitter::Update(float d){if(!m_enabled)return;m_numNew+=m_particleEmissionRate*d;for(unsigned n=static_cast<unsigned>(m_numNew);n;n--){CreateParticle();m_numNew-=1;}std::vector<unsigned>a;while(!m_alive.Empty())a.push_back(m_alive.Pop());for(unsigned i:a){MoveParticle(m_particles[i],d);if(m_particles[i].m_timeToLive<=0)DestroyParticle(i);else m_alive.Push(i);}}void CParticleEmitter::AddToModelScene(){for(unsigned n=0;n<m_alive.m_stackPointer;++n){unsigned i=m_alive.m_stack[n];if(i<m_particles.size()&&m_particles[i].m_timeToLive>0&&m_particles[i].m_hmodel)ModelAddToScene(*reinterpret_cast<CModel*>(m_particles[i].m_hmodel),0);}}void CParticleEmitter::Render(){for(unsigned n=0;n<m_alive.m_stackPointer;++n){unsigned i=m_alive.m_stack[n];if(i<m_particles.size()&&m_particles[i].m_timeToLive>0&&m_particles[i].m_hmodel)ModelRender(*reinterpret_cast<CModel*>(m_particles[i].m_hmodel),0);}}void CParticleEmitter::Flush(){for(auto&p:m_particles)p.Destroy();m_particles.clear();m_alive={};m_dead={};}void CParticleEmitter::SetVelocity(float v){m_velocity=v;}void CParticleEmitter::SetAcceleration(float v){m_acceleration=v;}void CParticleEmitter::SetScale(float v){m_scale=v;}void CParticleEmitter::SetLatitude(float v){m_latitude=v;}void CParticleEmitter::SetLongitude(float v){m_longitude=v;}void CParticleEmitter::SetParticleEmissionRate(float v){m_particleEmissionRate=v;}void CParticleEmitter::SetParticleLifeSpan(float v){if(v<0)throw std::invalid_argument("particle lifespan");m_particleLifeSpan=v;}void CParticleEmitter::SetModel(HMODEL__*v){m_hmodel=v;}unsigned CParticleEmitter::AddRef(){return++m_refCount;}unsigned CParticleEmitter::DecRef(){unsigned n=--m_refCount;if(!n)delete this;return n;}
